const settings = new SettingsStore();
const providerKeys = new ProviderKeysStore();
const sessions = new SessionsStore(); const backend = new IndexedDBStorageBackend({ dbName: 'my-app', version: 1, stores: [ settings.getConfig(), providerKeys.getConfig(), sessions.getConfig(), SessionsStore.getMetadataConfig(), ],
}); settings.setBackend(backend);
providerKeys.setBackend(backend);
sessions.setBackend(backend); const storage = new AppStorage(settings, providerKeys, sessions, undefined, backend);
setAppStorage(storage); // Create agent
const agent = new Agent({ initialState: { systemPrompt: 'You are a helpful assistant.', model: getModel('anthropic', 'claude-sonnet-4-5-20250929'), thinkingLevel: 'off', messages: [], tools: [], }, convertToLlm: defaultConvertToLlm,
}); // Create chat panel
const chatPanel = new ChatPanel();
await chatPanel.setAgent(agent, { onApiKeyRequired: (provider) => ApiKeyPromptDialog.prompt(provider),
}); document.body.appendChild(chatPanel);Architecture ┌─────────────────────────────────────────────────────┐
