replTool.runtimeProvidersFactory = () => [ new AttachmentsRuntimeProvider(attachments), new ArtifactsRuntimeProvider(artifactsPanel, agent, true), // read-write
]; agent.setTools([replTool]);Extract Document Extract text from documents at URLs:import { createExtractDocumentTool } from '@mariozechner/pi-web-ui'; const extractTool = createExtractDocumentTool();
extractTool.corsProxyUrl = 'https://corsproxy.io/?'; agent.setTools([extractTool]);Artifacts Tool Built into ArtifactsPanel, supports: HTML, SVG, Markdown, text, JSON, images, PDF, DOCX, XLSX.const artifactsPanel = new ArtifactsPanel();
