providerKeys.setBackend(backend);
sessions.setBackend(backend);
customProviders.setBackend(backend); // Create and set global storage
const storage = new AppStorage(settings, providerKeys, sessions, customProviders, backend);
setAppStorage(storage);SettingsStore Key-value settings:await storage.settings.set('proxy.enabled', true);
await storage.settings.set('proxy.url', 'https://proxy.example.com');
