const allMetadata = await storage.sessions.getAllMetadata(); // Update title
await storage.sessions.updateTitle(sessionId, 'New Title'); // Delete
await storage.sessions.delete(sessionId);CustomProvidersStore Custom LLM providers:const provider: CustomProvider = { id: crypto.randomUUID(), name: 'My Ollama', type: 'ollama', baseUrl: 'http://localhost:11434',
}; await storage.customProviders.set(provider);
const all = await storage.customProviders.getAll();Attachments Load and process files:import { loadAttachment, type Attachment } from '@mariozechner/pi-web-ui'; // From File input
const file = inputElement.files[0];
const attachment = await loadAttachment(file); // From URL
const attachment = await loadAttachment('https://example.com/doc.pdf'); // From ArrayBuffer
const attachment = await loadAttachment(arrayBuffer, 'document.pdf'); // Attachment structure
interface Attachment { id: string; type: 'image' | 'document'; fileName: string; mimeType: string; size: number; content: string; // base64 encoded extractedText?: string; // For documents preview?: string; // base64 preview image
} Supported formats: PDF, DOCX, XLSX, PPTX, images, text files.CORS Proxy For browser environments with CORS restrictions:import { createStreamFn, shouldUseProxyForProvider, isCorsError } from '@mariozechner/pi-web-ui'; // AgentInterface auto-configures proxy from settings
